  "113.2 Today's state: not checked in yet.": { ar: "حالة اليوم: لم يُسجَّل الحضور بعد.", tr: "Bugünün durumu: henüz giriş yapılmadı." },
  "113.2 Today's state: at school.": { ar: "حالة اليوم: في المدرسة.", tr: "Bugünün durumu: okulda." },
