  "113.2 Checked out before the end of the day.": { ar: "سجّل الانصراف قبل نهاية اليوم.", tr: "Gün bitmeden çıkış yaptı." },
  "113.2 The person's school day and when late starts.": { ar: "يوم الشخص في المدرسة ووقت بدء التأخر.", tr: "Kişinin okul günü ve geç sayılmanın başladığı saat." },
  "113.2 The field for the six digits shown at the school's gate.": { ar: "خانة الأرقام الستة الظاهرة عند بوابة المدرسة.", tr: "Okulun kapısında gösterilen altı hane için alan." },
