  "113.2 The phone's location couldn't be read.": { ar: "تعذّرت قراءة موقع الهاتف.", tr: "Telefonun konumu okunamadı." },
  "113.2 A check-in on time.": { ar: "تسجيل حضور في الموعد.", tr: "Zamanında yapılan giriş." },
  "113.2 A check-in after the school's late time.": { ar: "تسجيل حضور بعد وقت التأخر.", tr: "Geç sayılma saatinden sonra yapılan giriş." },
  "113.2 A check-out.": { ar: "تسجيل انصراف.", tr: "Yapılan çıkış." },
  "113.2 A check-out before the end of the day.": { ar: "تسجيل انصراف قبل نهاية اليوم.", tr: "Gün bitmeden yapılan çıkış." },
