  "113.3 The School tab of someone who works at the school and has no student there (no child, not a student).": { ar: "تبويب المدرسة لمن يعمل في المدرسة وليس له فيها طالب (لا ابن له فيها وليس طالبًا).", tr: "Okulda çalışan ve orada öğrencisi olmayan birinin Okul sekmesi (çocuğu yok, öğrenci değil)." },
