  "113.3 The School tab of someone who works at the school and has no student there (no child, not a student). For teachers.": { ar: "تبويب المدرسة لمن يعمل في المدرسة وليس له فيها طالب (لا ابن له فيها وليس طالبًا). للمعلمين.", tr: "Okulda çalışan ve orada öğrencisi olmayan birinin Okul sekmesi (çocuğu yok, öğrenci değil). Öğretmenler için." },
  "113.3 Opens the Staff tab from the School tab of someone who works at the school.": { ar: "يفتح تبويب الموظفين من تبويب المدرسة لمن يعمل في المدرسة.", tr: "Okulda çalışan birinin Okul sekmesinden Personel sekmesini açar." },
  "113.3 Opens the Classroom tab from the School tab of a teacher who has no student there.": { ar: "يفتح تبويب الفصل من تبويب المدرسة لمعلم ليس له فيها طالب.", tr: "Okulda öğrencisi olmayan bir öğretmenin Okul sekmesinden Sınıf sekmesini açar." },
  "113.6 The School tab's row and the screen of messages between teachers and families.": { ar: "صف تبويب المدرسة وشاشة الرسائل بين المعلمين والأسر.", tr: "Okul sekmesindeki satır ve öğretmenlerle aileler arasındaki mesajların ekranı." },
  "113.6 Under Messages on the School tab, for a parent or a student.": { ar: "تحت الرسائل في تبويب المدرسة، لولي الأمر أو الطالب.", tr: "Okul sekmesinde Mesajlar'ın altında, veli veya öğrenci için." },
  "113.6 Under Messages in the Classroom tab, for a teacher.": { ar: "تحت الرسائل في تبويب الفصل، للمعلم.", tr: "Sınıf sekmesinde Mesajlar'ın altında, öğretmen için." },
