  "113.6 The heading of the parents and students a teacher can write to.": { ar: "عنوان أولياء الأمور والطلاب الذين يستطيع المعلم مراسلتهم.", tr: "Öğretmenin yazabileceği veli ve öğrencilerin başlığı." },
