  "113.6 When the school doesn't allow photos and files.": { ar: "عندما لا تسمح المدرسة بالصور والملفات.", tr: "Okul fotoğraf ve dosyalara izin vermediğinde." },
  "113.6 The privacy note in a conversation the school may read.": { ar: "ملاحظة الخصوصية في محادثة يمكن للمدرسة قراءتها.", tr: "Okulun okuyabildiği bir konuşmadaki gizlilik notu." },
  "113.6 The privacy note in a conversation the school doesn't read.": { ar: "ملاحظة الخصوصية في محادثة لا تقرؤها المدرسة.", tr: "Okulun okumadığı bir konuşmadaki gizlilik notu." },
  "113.6 Messages without contacts.": { ar: "الرسائل بلا جهات اتصال.", tr: "Kişisi olmayan mesajlar." },
  "113.6 A teacher's button to write to a whole class at once.": { ar: "زر المعلم لمراسلة فصل كامل دفعة واحدة.", tr: "Öğretmenin bir sınıfın tamamına tek seferde yazma düğmesi." },
  "113.6 The title of the sheet to write to a whole class.": { ar: "عنوان نافذة مراسلة فصل كامل.", tr: "Bir sınıfın tamamına yazma penceresinin başlığı." },
  "113.6 Whom a class message goes to.": { ar: "إلى من تُرسل رسالة الفصل.", tr: "Sınıf mesajının kime gideceği." },
