  "113.8 The school's calendar: events, holidays and exams.": { ar: "تقويم المدرسة: الفعاليات والعطلات والامتحانات.", tr: "Okulun takvimi: etkinlikler, tatiller ve sınavlar." },
  "113.8 The exams' timetable of the student's class.": { ar: "جدول امتحانات فصل الطالب.", tr: "Öğrencinin sınıfının sınav programı." },
