  "113.8 Shows the school's calendar a month at a time.": { ar: "يعرض تقويم المدرسة شهرًا بشهر.", tr: "Okul takvimini ay ay gösterir." },
  "113.8 Shows the school's calendar as a list of what is coming.": { ar: "يعرض تقويم المدرسة قائمةً بما هو قادم.", tr: "Okul takvimini yaklaşanların listesi olarak gösterir." },
  "113.8 A day of the school's calendar without events or exams.": { ar: "يوم في تقويم المدرسة بلا فعاليات أو امتحانات.", tr: "Okul takviminde etkinlik veya sınav olmayan bir gün." },
  "113.8 The school's calendar list with nothing coming.": { ar: "قائمة تقويم المدرسة وليس فيها شيء قادم.", tr: "Yaklaşan bir şey olmayan okul takvimi listesi." },
  "113.8 An event of the school's calendar that lasts all day.": { ar: "فعالية في تقويم المدرسة تستمر طوال اليوم.", tr: "Okul takviminde tüm gün süren bir etkinlik." },
  "113.8 Label of a holiday or a break on the school's calendar.": { ar: "وسم العطلة أو الإجازة في تقويم المدرسة.", tr: "Okul takviminde tatil etiketi." },
  "113.8 Label of exam days on the school's calendar.": { ar: "وسم أيام الامتحانات في تقويم المدرسة.", tr: "Okul takviminde sınav günleri etiketi." },
  "113.8 Label of an exam of the timetable on the school's calendar.": { ar: "وسم امتحان من الجدول في تقويم المدرسة.", tr: "Okul takviminde programdaki bir sınavın etiketi." },
  "113.8 An event of the school's calendar for the staff only.": { ar: "فعالية في تقويم المدرسة للعاملين فقط.", tr: "Okul takviminde yalnızca çalışanlar için bir etkinlik." },
  "113.8 The days of an event of the school's calendar that lasts several days.": { ar: "أيام فعالية في تقويم المدرسة تستمر عدة أيام.", tr: "Okul takviminde birkaç gün süren bir etkinliğin günleri." },
  "113.8 How many events and exams a day of the school's calendar has, for screen readers.": { ar: "عدد الفعاليات والامتحانات في يوم من تقويم المدرسة، لقارئات الشاشة.", tr: "Okul takviminde bir günün etkinlik ve sınav sayısı, ekran okuyucular için." },
  "113.8 The exams still to come on the exams' timetable.": { ar: "الامتحانات القادمة في جدول الامتحانات.", tr: "Sınav programında yaklaşan sınavlar." },
  "113.8 The exams already done on the exams' timetable.": { ar: "الامتحانات المنتهية في جدول الامتحانات.", tr: "Sınav programında yapılmış sınavlar." },
  "113.8 The exams' timetable with no exams published.": { ar: "جدول الامتحانات ولم يُنشر فيه امتحان.", tr: "Yayınlanmış sınavı olmayan sınav programı." },
  "113.8 Under the empty exams' timetable.": { ar: "تحت جدول الامتحانات الفارغ.", tr: "Boş sınav programının altında." },
  "113.8 When an exam is and how long it takes.": { ar: "موعد الامتحان ومدته.", tr: "Sınavın saati ve süresi." },
  "113.8 The points total of a student's behaviour record.": { ar: "مجموع نقاط سجل سلوك الطالب.", tr: "Öğrencinin davranış kaydının puan toplamı." },
  "113.8 How many merits a student's behaviour record has.": { ar: "عدد نقاط التميز في سجل سلوك الطالب.", tr: "Öğrencinin davranış kaydındaki takdir sayısı." },
  "113.8 How many negative notes a student's behaviour record has.": { ar: "عدد الملاحظات السلبية في سجل سلوك الطالب.", tr: "Öğrencinin davranış kaydındaki olumsuz not sayısı." },
  "113.8 A student's behaviour record with nothing in it.": { ar: "سجل سلوك طالب ليس فيه شيء.", tr: "İçinde bir şey olmayan öğrenci davranış kaydı." },
  "113.8 A merit or a note the school wrote, not a teacher.": { ar: "نقطة تميز أو ملاحظة كتبتها المدرسة لا معلم.", tr: "Bir öğretmenin değil okulun yazdığı takdir veya not." },
  "113.8 The points of a merit (+2) or a note (-1).": { ar: "نقاط التميز (+2) أو الملاحظة (-1).", tr: "Bir takdirin (+2) veya notun (-1) puanı." },
  "113.8 Button and sheet title in the Classroom tab's class behaviour.": { ar: "زر وعنوان النافذة في سلوك الفصل بتبويب الفصل.", tr: "Sınıf sekmesindeki sınıf davranışında düğme ve sayfa başlığı." },
  "113.8 Whom the teacher writes a merit or a note for.": { ar: "الطالب الذي يكتب له المعلم نقطة التميز أو الملاحظة.", tr: "Öğretmenin takdir veya not yazdığı öğrenci." },
  "113.8 The school's category of a merit or a note, to choose.": { ar: "فئة المدرسة لنقطة التميز أو الملاحظة، للاختيار.", tr: "Takdir veya not için okulun kategorisi, seçmek için." },
  "113.8 The words a teacher adds to a merit or a note.": { ar: "الكلمات التي يضيفها المعلم إلى نقطة التميز أو الملاحظة.", tr: "Öğretmenin takdire veya nota eklediği sözler." },
  "113.8 After a teacher wrote a merit or a note.": { ar: "بعد أن كتب المعلم نقطة تميز أو ملاحظة.", tr: "Öğretmen bir takdir veya not yazdıktan sonra." },
  "113.8 A teacher sends a merit or a note without its category.": { ar: "المعلم يرسل نقطة تميز أو ملاحظة دون فئة.", tr: "Öğretmen kategorisiz takdir veya not gönderiyor." },
  "113.8 Removes a merit or a note the teacher wrote today.": { ar: "يحذف نقطة تميز أو ملاحظة كتبها المعلم اليوم.", tr: "Öğretmenin bugün yazdığı takdiri veya notu kaldırır." },
  "113.8 After a teacher took back a merit or a note.": { ar: "بعد أن تراجع المعلم عن نقطة تميز أو ملاحظة.", tr: "Öğretmen bir takdiri veya notu geri aldıktan sonra." },
  "113.8 The class's latest merits and notes.": { ar: "أحدث نقاط التميز والملاحظات في الفصل.", tr: "Sınıfın en yeni takdirleri ve notları." },
  "113.8 A teacher opens behaviour before the school set any categories.": { ar: "يفتح المعلم السلوك قبل أن تحدد المدرسة أي فئات.", tr: "Öğretmen, okul kategori belirlemeden davranışı açıyor." },
  "113.8 The attendance register on a holiday or a break of the school's calendar.": { ar: "سجل الحضور في يوم عطلة أو إجازة من تقويم المدرسة.", tr: "Okul takviminde tatil gününde yoklama listesi." },
