  "113.1 How many courses a bundle has.": { ar: "عدد الدورات في الحزمة.", tr: "Bir paketteki kurs sayısı." },
  "113.1 What a bundle's courses cost on their own, next to the bundle's price.": { ar: "سعر دورات الحزمة منفردة، بجانب سعر الحزمة.", tr: "Paketin kurslarının tek tek fiyatı, paket fiyatının yanında." },
  "113.1 Above the price on a bundle's page.": { ar: "فوق السعر في صفحة الحزمة.", tr: "Paket sayfasında fiyatın üstünde." },
  "113.1 Buys a bundle of courses.": { ar: "يشتري حزمة الدورات.", tr: "Kurs paketini satın alır." },
  "113.1 The heading of a bundle's courses on its page.": { ar: "عنوان دورات الحزمة في صفحتها.", tr: "Paket sayfasında kurslarının başlığı." },
  "113.1 On a bundle's page, when the student has some of its courses.": { ar: "في صفحة الحزمة، عندما يملك الطالب بعض دوراتها.", tr: "Paket sayfasında, öğrencinin bazı kursları zaten varsa." },
  "113.1 On a bundle's page, when the student has all its courses.": { ar: "في صفحة الحزمة، عندما يملك الطالب كل دوراتها.", tr: "Paket sayfasında, öğrencinin tüm kursları varsa." },
  "113.1 After a bundle was bought or a coupon made it free.": { ar: "بعد شراء الحزمة أو جعل القسيمة لها مجانية.", tr: "Paket satın alındıktan ya da bir kupon onu ücretsiz yaptıktan sonra." },
  "113.1 Opens My courses from a bundle the student has.": { ar: "يفتح «دوراتي» من حزمة يملكها الطالب.", tr: "Öğrencinin sahip olduğu bir paketten Kurslarım'ı açar." },
  "113.1 On a course's page: the bundles that have it.": { ar: "في صفحة الدورة: الحزم التي تضمّها.", tr: "Kurs sayfasında: onu içeren paketler." },
  "113.1 A bundle the app doesn't sell on this phone.": { ar: "حزمة لا يبيعها التطبيق على هذا الهاتف.", tr: "Uygulamanın bu telefonda satmadığı bir paket." },
  "113.1 While a bundle's page loads.": { ar: "أثناء تحميل صفحة الحزمة.", tr: "Paket sayfası yüklenirken." },
  "113.1 A coupon that takes the whole price.": { ar: "قسيمة تخصم السعر كاملًا.", tr: "Fiyatın tamamını düşen kupon." },
  "113.1 Enrolls with a coupon that takes the whole price, without paying.": { ar: "يسجّل بقسيمة تخصم السعر كاملًا، دون دفع.", tr: "Fiyatın tamamını düşen bir kuponla ödeme yapmadan kaydeder." },
  "113.4 The bottom tab only the school's parents see: their children's days, slips, excuses and pick-up.": { ar: "التبويب السفلي الذي يراه أولياء أمور المدرسة فقط: أيام أبنائهم والأذونات والأعذار والاستلام.", tr: "Yalnızca okulun velilerinin gördüğü alt sekme: çocuklarının günleri, formlar, mazeretler ve teslim alma." },
  "113.4 The Parent tab, for someone the school didn't add as a parent: its title.": { ar: "تبويب ولي الأمر لشخص لم تضفه المدرسة وليَّ أمر: عنوانه.", tr: "Okulun veli olarak eklemediği biri için Veli sekmesi: başlığı." },
  "113.4 The Parent tab, for someone the school didn't add as a parent: what to do.": { ar: "تبويب ولي الأمر لشخص لم تضفه المدرسة وليَّ أمر: ما عليه فعله.", tr: "Okulun veli olarak eklemediği biri için Veli sekmesi: ne yapacağı." },
  "113.4 On the School tab of a parent who isn't a student: their children's days are in the Parent tab.": { ar: "في تبويب المدرسة لولي أمر ليس طالبًا: أيام أبنائه في تبويب ولي الأمر.", tr: "Öğrenci olmayan bir velinin Okul sekmesinde: çocuklarının günleri Veli sekmesinde." },
  "113.4 On the School tab of a parent who isn't a student: what the Parent tab has.": { ar: "في تبويب المدرسة لولي أمر ليس طالبًا: ما في تبويب ولي الأمر.", tr: "Öğrenci olmayan bir velinin Okul sekmesinde: Veli sekmesinde neler olduğu." },
  "113.4 Button on the School tab of a parent: opens the Parent tab.": { ar: "زر في تبويب المدرسة لولي الأمر: يفتح تبويب ولي الأمر.", tr: "Velinin Okul sekmesindeki düğme: Veli sekmesini açar." },
  "113.4 On a child's day: today is a holiday or a break.": { ar: "في يوم الطالب: اليوم عطلة أو إجازة.", tr: "Çocuğun gününde: bugün tatil." },
  "113.4 On a child's day: who picks the child up today.": { ar: "في يوم الطالب: من يستلمه اليوم.", tr: "Çocuğun gününde: bugün onu kimin alacağı." },
  "113.4 On a child's day: the child's check-in today.": { ar: "في يوم الطالب: حضوره وانصرافه اليوم.", tr: "Çocuğun gününde: bugünkü giriş-çıkışı." },
  "113.4 On a child's day: how much homework is due.": { ar: "في يوم الطالب: عدد الواجبات المستحقة.", tr: "Çocuğun gününde: teslim edilecek ödev sayısı." },
  "113.4 On a child's day: the three latest scores.": { ar: "في يوم الطالب: آخر ثلاث درجات.", tr: "Çocuğun gününde: son üç not." },
  "113.4 On a child's day: the child's behaviour points.": { ar: "في يوم الطالب: نقاط سلوكه.", tr: "Çocuğun gününde: davranış puanları." },
  "113.4 On a child's day: the library books out now.": { ar: "في يوم الطالب: كتب المكتبة المعارة الآن.", tr: "Çocuğun gününde: şu an ödünç alınmış kütüphane kitapları." },
  "113.4 On a child's day: when a library book is due back.": { ar: "في يوم الطالب: موعد إعادة كتاب المكتبة.", tr: "Çocuğun gününde: kütüphane kitabının iade tarihi." },
  "113.4 On a child's day: a library book that is overdue.": { ar: "في يوم الطالب: كتاب مكتبة متأخر.", tr: "Çocuğun gününde: gecikmiş bir kütüphane kitabı." },
  "113.4 On a child's day: the child's bus is running now.": { ar: "في يوم الطالب: حافلته في رحلة الآن.", tr: "Çocuğun gününde: servisi şu an yolda." },
