  "113.4 The list of a child's parts on the Parent tab.": { ar: "قائمة أجزاء الطالب في تبويب ولي الأمر.", tr: "Veli sekmesinde çocuğun bölümlerinin listesi." },
  "113.4 Opens the permission slips to sign.": { ar: "يفتح أذونات الموافقة التي تحتاج إلى توقيع.", tr: "İmzalanacak izin formlarını açar." },
