  "113.4 Under the absence excuses tile.": { ar: "تحت خانة أعذار الغياب.", tr: "Devamsızlık mazeretleri satırının altında." },
  "113.4 Opens who may pick the child up.": { ar: "يفتح قائمة من يُسمح له باستلام الطالب.", tr: "Çocuğu kimin alabileceğini açar." },
