  "113.4 A child's slip signed no.": { ar: "إذن الطالب موقّع بلا.", tr: "Çocuğun formu hayır diye imzalandı." },
  "113.4 A child's slip not answered yet.": { ar: "إذن الطالب لم يُجب عنه بعد.", tr: "Çocuğun formu henüz yanıtlanmadı." },
  "113.4 What a parent signs when they answer yes.": { ar: "ما يوقّعه ولي الأمر عند الإجابة بنعم.", tr: "Velinin evet derken imzaladığı metin." },
  "113.4 What a parent signs when they answer no.": { ar: "ما يوقّعه ولي الأمر عند الإجابة بلا.", tr: "Velinin hayır derken imzaladığı metin." },
  "113.4 The name a parent signs a slip with.": { ar: "الاسم الذي يوقّع به ولي الأمر الإذن.", tr: "Velinin formu imzaladığı ad." },
  "113.4 Signs the permission slip.": { ar: "يوقّع إذن الموافقة.", tr: "İzin formunu imzalar." },
  "113.4 After a parent signed a slip.": { ar: "بعد توقيع ولي الأمر الإذن.", tr: "Veli formu imzaladıktan sonra." },
  "113.4 The permission slips list when there is none.": { ar: "قائمة أذونات الموافقة حين لا يوجد شيء.", tr: "Hiç form yokken izin formları listesi." },
  "113.4 A slip signed without a name.": { ar: "إذن وُقّع دون اسم.", tr: "Adsız imzalanmış form." },
