  "113.4 Adds a photo of a doctor's note to an excuse.": { ar: "يضيف صورة شهادة طبية إلى العذر.", tr: "Mazerete doktor raporu fotoğrafı ekler." },
  "113.4 Adds a PDF to an excuse.": { ar: "يضيف ملف PDF إلى العذر.", tr: "Mazerete PDF ekler." },
