  "113.4 The school's note with its answer to an excuse.": { ar: "ملاحظة المدرسة مع ردّها على العذر.", tr: "Okulun mazerete yanıtıyla birlikte notu." },
  "113.4 At the top of the pick-up screen.": { ar: "أعلى شاشة الاستلام.", tr: "Teslim alma ekranının üstünde." },
  "113.4 The pick-up list when empty.": { ar: "قائمة الاستلام حين تكون فارغة.", tr: "Boşken teslim alma listesi." },
