  "113.4 A pick-up person's name.": { ar: "اسم الشخص الذي يستلم الطالب.", tr: "Çocuğu alacak kişinin adı." },
  "113.4 A pick-up person's relation to the child (grandmother, uncle…).": { ar: "صلة قرابة من يستلم الطالب (جدة، عم…).", tr: "Çocuğu alacak kişinin yakınlığı (büyükanne, amca…)." },
  "113.4 A pick-up person's phone number.": { ar: "رقم هاتف من يستلم الطالب.", tr: "Çocuğu alacak kişinin telefonu." },
