  "113.4 What the one-day pick-up note is for.": { ar: "الغرض من ملاحظة الاستلام ليوم واحد.", tr: "Bir günlük teslim alma notunun amacı." },
  "113.4 The day of a one-day pick-up note.": { ar: "يوم ملاحظة الاستلام.", tr: "Bir günlük teslim alma notunun günü." },
  "113.4 A one-day pick-up note's note.": { ar: "نص ملاحظة الاستلام ليوم واحد.", tr: "Bir günlük teslim alma notunun metni." },
  "113.4 Sends a one-day pick-up note.": { ar: "يرسل ملاحظة الاستلام ليوم واحد.", tr: "Bir günlük teslim alma notunu gönderir." },
  "113.4 After a one-day pick-up note was sent.": { ar: "بعد إرسال ملاحظة الاستلام ليوم واحد.", tr: "Bir günlük teslim alma notu gönderildikten sonra." },
  "113.4 A one-day pick-up note: the day and who picks up.": { ar: "ملاحظة استلام ليوم واحد: اليوم ومن يستلم.", tr: "Bir günlük teslim alma notu: gün ve alacak kişi." },
  "113.4 Deletes a one-day pick-up note.": { ar: "يحذف ملاحظة الاستلام ليوم واحد.", tr: "Bir günlük teslim alma notunu siler." },
  // 113.12 Payslips.
  "113.12 Opens the person's own payslips (Staff and Classroom tabs).": { ar: "يفتح قسائم راتب الشخص (تبويبا الموظفين والفصل).", tr: "Kişinin kendi bordrolarını açar (Personel ve Sınıf sekmeleri)." },
  "113.12 The payslips list is empty.": { ar: "قائمة القسائم فارغة.", tr: "Bordro listesi boş." },
