  "113.12 A final payslip the school hasn't recorded as paid.": { ar: "قسيمة نهائية لم تسجّلها المدرسة مدفوعة.", tr: "Okulun ödendi olarak kaydetmediği kesin bordro." },
  "113.12 A payslip paid in part.": { ar: "قسيمة دُفع جزء منها.", tr: "Kısmen ödenmiş bordro." },
  "113.12 A payslip paid in full.": { ar: "قسيمة دُفعت كاملة.", tr: "Tamamı ödenmiş bordro." },
  "113.12 A payslip's net pay on the list.": { ar: "صافي الراتب في القائمة.", tr: "Listede bordronun net ödemesi." },
  "113.12 A payslip's base salary.": { ar: "الراتب الأساسي في القسيمة.", tr: "Bordrodaki temel maaş." },
  "113.12 A bonus line without a name.": { ar: "بند مكافأة بلا اسم.", tr: "Adsız prim kalemi." },
  "113.12 A deduction line without a name.": { ar: "بند خصم بلا اسم.", tr: "Adsız kesinti kalemi." },
  "113.12 A deduction for days absent, with how many.": { ar: "خصم عن أيام الغياب مع عددها.", tr: "Devamsızlık günleri için kesinti, kaç gün olduğuyla." },
  "113.12 A deduction for coming late, with how many times.": { ar: "خصم عن التأخير مع عدد مراته.", tr: "Geç kalma için kesinti, kaç kez olduğuyla." },
  "113.12 Part of an advance taken back from the pay.": { ar: "جزء من سلفة يُسترد من الراتب.", tr: "Ücretten düşülen avans kısmı." },
