  "113.12 What is still to be paid.": { ar: "ما بقي للدفع.", tr: "Ödenecek kalan." },
  "113.12 The payments the school recorded.": { ar: "الدفعات التي سجّلتها المدرسة.", tr: "Okulun kaydettiği ödemeler." },
  "113.12 A payment in cash, on a day.": { ar: "دفعة نقدية في يوم.", tr: "Bir gün yapılan nakit ödeme." },
  "113.12 A payment by bank transfer, on a day.": { ar: "دفعة بتحويل بنكي في يوم.", tr: "Bir gün yapılan banka havalesi." },
  "113.12 The month's days at the gate on a payslip.": { ar: "أيام الشهر عند البوابة في القسيمة.", tr: "Bordroda ayın kapıdaki günleri." },
  "113.12 Opens the payslip's PDF in the app's viewer.": { ar: "يفتح ملف PDF للقسيمة في عارض التطبيق.", tr: "Bordronun PDF'ini uygulamanın görüntüleyicisinde açar." },
  "113.12 Opens the payslip's PDF outside the app, to keep it.": { ar: "يفتح ملف PDF للقسيمة خارج التطبيق للاحتفاظ به.", tr: "Bordronun PDF'ini saklamak için uygulama dışında açar." },
  "113.12 The person's advances still being taken back.": { ar: "سُلف الشخص التي ما زالت تُسترد.", tr: "Kişinin hâlâ düşülen avansları." },
  "113.12 An advance: how much, when, each month's part and what is left.": { ar: "سلفة: مبلغها وتاريخها والقسط الشهري والمتبقي.", tr: "Bir avans: ne kadar, ne zaman, aylık taksit ve kalan." },
  // 113.9 Universities
  "113.9 Opens a university student's registration for the term.": { ar: "يفتح تسجيل طالب الجامعة للفصل الدراسي.", tr: "Üniversite öğrencisinin dönem kaydını açar." },
  "113.9 Opens a university student's week of lectures.": { ar: "يفتح أسبوع محاضرات طالب الجامعة.", tr: "Üniversite öğrencisinin haftalık derslerini açar." },
  "113.9 Opens a university student's results by term.": { ar: "يفتح نتائج طالب الجامعة في كل فصل.", tr: "Üniversite öğrencisinin dönem dönem sonuçlarını açar." },
  "113.9 Opens a university student's transcript.": { ar: "يفتح السجل الأكاديمي لطالب الجامعة.", tr: "Üniversite öğrencisinin transkriptini açar." },
  "113.9 Opens the courses of the student's program: done, in progress and left.": { ar: "يفتح مقررات برنامج الطالب: المنجزة والجارية والمتبقية.", tr: "Öğrencinin programındaki dersleri açar: tamamlanan, devam eden ve kalan." },
  "113.9 The label of a university student's cumulative GPA.": { ar: "عنوان المعدل التراكمي لطالب الجامعة.", tr: "Üniversite öğrencisinin genel not ortalamasının etiketi." },
  "113.9 The credits a student earned of those their program needs.": { ar: "الساعات التي اجتازها الطالب من الساعات اللازمة لبرنامجه.", tr: "Öğrencinin programın gerektirdiği kredilerden kazandığı." },
  "113.9 A course's or a term's credits.": { ar: "ساعات مقرر أو فصل دراسي.", tr: "Bir dersin veya dönemin kredisi." },
