  "113.9 The term's registration and drop days are over.": { ar: "انتهت فترة التسجيل والحذف للفصل.", tr: "Dönemin kayıt ve bırakma günleri bitti." },
  "113.9 The credits a student holds this term and the program's least and most.": { ar: "ساعات الطالب في هذا الفصل، وأقل وأكثر ما يسمح به البرنامج.", tr: "Öğrencinin bu dönemki kredisi ve programın en az ve en çok sınırı." },
  "113.9 The sections a student holds this term, or a lecturer teaches.": { ar: "الشُّعب التي يسجلها الطالب في هذا الفصل أو يدرّسها المحاضر.", tr: "Öğrencinin bu dönem aldığı veya öğretim üyesinin verdiği şubeler." },
  "113.9 The term's other sections a student can add.": { ar: "شُعب الفصل الأخرى التي يمكن للطالب إضافتها.", tr: "Öğrencinin ekleyebileceği diğer şubeler." },
