  "113.9 The percent a lecturer gives; the scale's letter comes from it.": { ar: "النسبة المئوية التي يعطيها المحاضر؛ ومنها يأتي حرف السلّم.", tr: "Öğretim üyesinin verdiği yüzde; harf notu ondan çıkar." },
