  "115 The vendor's screens for someone who doesn't work for a vendor: the title.": { ar: "شاشات البائع لشخص لا يعمل لدى أي بائع: العنوان.", tr: "Bir satıcıda çalışmayan biri için satıcı ekranları: başlık." },
