  "115.16 The button on a grocery's or shop's order that opens its picking, and that screen's title.": { ar: "زر في طلب البقالة أو المتجر يفتح تجهيز أصنافه، وعنوان تلك الشاشة.", tr: "Market veya mağaza siparişinde ürün toplamayı açan düğme ve o ekranın başlığı." },
