  "115.16 Under the weight: how much more than ordered the customer agreed to.": { ar: "تحت الوزن: كم يزيد عن المطلوب مما وافق عليه العميل.", tr: "Ağırlığın altında: müşterinin siparişten ne kadar fazlasını kabul ettiği." },
  "115.16 What the customer asked for when an item is out: a similar one.": { ar: "ما طلبه العميل إن لم يتوفر الصنف: صنف مشابه.", tr: "Ürün yoksa müşterinin isteği: benzer bir ürün." },
  "115.16 What the customer asked for when an item is out: the one they chose.": { ar: "ما طلبه العميل إن لم يتوفر الصنف: الصنف الذي اختاره.", tr: "Ürün yoksa müşterinin isteği: seçtiği ürün." },
  "115.16 What the customer asked for when an item is out: nothing instead.": { ar: "ما طلبه العميل إن لم يتوفر الصنف: لا شيء بدلًا منه.", tr: "Ürün yoksa müşterinin isteği: yerine bir şey gelmesin." },
  "115.16 A swapped line whose substitute the customer chose.": { ar: "صنف مستبدل اختار العميل بديله.", tr: "Yerine geçecek ürünü müşterinin seçtiği değiştirilmiş satır." },
  "115.16 Opens the vendor's items to choose what to bring instead.": { ar: "يفتح أصناف المتجر لاختيار ما يُحضر بدلًا من الصنف.", tr: "Yerine getirilecek ürünü seçmek için işletmenin ürünlerini açar." },
  "115.16 Next to the chosen substitute: choose another.": { ar: "بجانب البديل المختار: اختيار بديل آخر.", tr: "Seçilen ürünün yanında: başka birini seçer." },
