  "115.16 Under a line of the order: the amount picked.": { ar: "تحت صنف في الطلب: الكمية التي جُهّزت.", tr: "Siparişteki bir ürünün altında: toplanan miktar." },
  "115.16 Under a line of the order: the item brought instead.": { ar: "تحت صنف في الطلب: الصنف الذي أُحضر بدلًا منه.", tr: "Siparişteki bir ürünün altında: yerine getirilen ürün." },
  "115.16 The vendor's monthly statements: the button and the screen's title.": { ar: "كشوف الحساب الشهرية للمتجر: الزر وعنوان الشاشة.", tr: "İşletmenin aylık hesap özetleri: düğme ve ekran başlığı." },
