  "115.16 The month's delivered orders, next to their total.": { ar: "طلبات الشهر المُسلّمة، بجانب إجماليها.", tr: "Ayın teslim edilen siparişleri, toplamlarının yanında." },
  "115.16 What the vendor earns on the month's orders.": { ar: "ما يربحه المتجر من طلبات الشهر.", tr: "İşletmenin ayın siparişlerinden kazancı." },
